let decision={};
if(outputs.analysis_json&&typeof outputs.analysis_json==='object'){decision=outputs.analysis_json;}
else if($json.analysis_json&&typeof $json.analysis_json==='object'){decision=$json.analysis_json;}
else if(Array.isArray(outputs.verdicts)||outputs.action||outputs.dashboardSummary){decision=outputs;}
