else{
const raw=String(outputs.text||outputs.result||outputs.analysis_json||$json.analysis_json||$json.data?.analysis_json||$json.answer||$json.text||'');
try{decision=JSON.parse(raw.trim());}catch(e){
const object=text=>{let start=-1,depth=0,q=false,esc=false,last;for(let i=0;i<text.length;i++){const c=text[i];if(q){if(esc)esc=false;else if(c==='\\')esc=true;else if(c==='"')q=false;continue;}if(c==='"'){q=true;continue;}if(c==='{'){if(!depth)start=i;depth++;}else if(c==='}'&&depth&&!--depth){try{last=JSON.parse(text.slice(start,i+1));}catch{}}}return last;};
decision=object(raw)||{};
}
}
console.log('ParseDify: keys='+Object.keys(decision).join(',')+' verdicts='+((decision.verdicts||[]).length));
return [{json:{difyText:JSON.stringify(decision).slice(-20000),decision}}];

const norm=$('Normalize Batch').first().json,parsed=$json,job=norm.job||{},source=job.cases||[];
