verificationReason:text(raw.verificationReason,600)
},evidence:{evidenceChain:[]}}});
console.log('BuildCallback: results='+results.length+' matched='+matched.size+' callbackUrl='+callbackUrl);return[{json:{callbackUrl:norm.callbackUrl||'http://127.0.0.1:8787/api/metabase-anomaly-analysis/batch-callback',runId:job.runId,countryCode:job.countryCode,jobId:norm.jobId,callbackToken:norm.callbackToken,results}}];
